// Minimal mock of the parts of @minecraft/server used by the addon,
// just enough to exercise our own logic end-to-end outside the game.

const blockStore = new Map();
const containerStore = new Map();
const signStore = new Map();
const entities = [];
const messageLog = [];

function key(loc) { return `${loc.x},${loc.y},${loc.z}`; }

/**
 * Container.addItem does NOT throw when there is no room, and it does NOT
 * silently discard the overflow either: it returns the ItemStack that could
 * not be placed (see
 * learn.microsoft.com/minecraft/creator/scriptapi/minecraft/server/container#additem,
 * "Returns: ItemStack | undefined").
 *
 * The old mock modelled neither half of that: it dropped the stack whole into
 * the first empty slot without stacking, and returned undefined whether the
 * item landed or not. Both gaps mattered:
 *
 *  - no stacking meant a container the real engine would have merged into
 *    looked full here (and vice versa), so free-space maths could not be
 *    tested at all;
 *  - always returning undefined meant a caller that ignores the return value
 *    was indistinguishable from one that checks it. That is what let four
 *    reward paths (contracts.js, special_content.js, specials.js, quests.js)
 *    ship a turn-in that takes the player's items, finds no room for the
 *    reward, and destroys it - with a fully green test suite, because the
 *    mock never had a way to say "that did not fit".
 *
 * craftsman_quests.js and sentinel_quests.js always did this correctly by
 * reserving the slot up front; the mock could not tell the difference between
 * them and the four that did not.
 */
function makeContainer(size = 27) {
  const items = new Array(size).fill(undefined);
  const MAX_STACK = 64;
  return {
    size,
    get emptySlotsCount() { return items.filter((slot) => !slot).length; },
    getItem(i) { return items[i]; },
    setItem(i, stack) { items[i] = stack; },
    addItem(stack) {
      if (!stack) return undefined;
      let remaining = stack.amount === undefined ? 1 : stack.amount;
      // Top up matching partial stacks first, exactly as the engine does.
      for (let i = 0; i < items.length && remaining > 0; i++) {
        const existing = items[i];
        if (!existing || existing.typeId !== stack.typeId) continue;
        const room = MAX_STACK - existing.amount;
        if (room <= 0) continue;
        const moved = Math.min(room, remaining);
        existing.amount += moved;
        remaining -= moved;
      }
      // Then spill into empty slots.
      for (let i = 0; i < items.length && remaining > 0; i++) {
        if (items[i]) continue;
        const moved = Math.min(MAX_STACK, remaining);
        const placed = typeof stack.clone === "function" ? stack.clone() : new ItemStack(stack.typeId, moved);
        placed.amount = moved;
        items[i] = placed;
        remaining -= moved;
      }
      if (remaining <= 0) return undefined;
      const leftover = typeof stack.clone === "function" ? stack.clone() : new ItemStack(stack.typeId, remaining);
      leftover.amount = remaining;
      return leftover;
    },
    _raw: items
  };
}

// Emulates the engine's block-state validation closely enough to catch
// outdated schemes: doors moved to minecraft:cardinal_direction in 1.21.60,
// so an integer "direction" state on a door must be REJECTED here.
const VALID_STATES = {
  door: new Set(["minecraft:cardinal_direction", "upper_block_bit", "open_bit", "door_hinge_bit"]),
  stairs: new Set(["weirdo_direction", "upside_down_bit"]),
  chestlike: new Set(["minecraft:cardinal_direction", "facing_direction"]),
  bed: new Set(["minecraft:cardinal_direction", "direction", "head_piece_bit", "occupied_bit"]),
  any: null
};
function categoryOf(typeId) {
  if (typeId.includes("_door")) return "door";
  if (typeId.includes("_stairs")) return "stairs";
  if (["minecraft:chest","minecraft:furnace","minecraft:blast_furnace","minecraft:barrel",
       "minecraft:lectern","minecraft:composter","minecraft:cartography_table",
       "minecraft:anvil","minecraft:wall_banner","minecraft:frame","minecraft:bell"].includes(typeId)) return "chestlike";
  if (typeId === "minecraft:bed") return "bed";
  return "any";
}
/**
 * Block identifiers that LOOK plausible but do not exist in Bedrock. The real
 * engine throws on these; the mock used to accept anything, which is how
 * `cobblestone_stairs` shipped in 0.4.x and how `oak_fence_gate`,
 * `oak_pressure_plate`, `stonecutter` and `bricks` survived until the 0.5.4
 * audit against the official Block enum.
 *
 * Every entry here was confirmed ABSENT from
 * learn.microsoft.com/minecraft/creator/commands/enums/block (stable channel).
 * The right-hand side is the identifier that actually works.
 *
 * Add to this list whenever a bad id is found - that is what stops the same
 * class of bug from recurring silently behind a green test run.
 */
const KNOWN_INVALID_BLOCK_IDS = new Map([
  ["minecraft:cobblestone_stairs", "minecraft:stone_stairs"],
  ["minecraft:oak_fence_gate", "minecraft:fence_gate"],
  ["minecraft:oak_pressure_plate", "minecraft:wooden_pressure_plate"],
  ["minecraft:stonecutter", "minecraft:stonecutter_block"],
  ["minecraft:bricks", "minecraft:brick_block"],
  ["minecraft:oak_standing_sign", "minecraft:standing_sign"],
  ["minecraft:rooted_dirt", "minecraft:dirt_with_roots"],
  ["minecraft:snow_block", "minecraft:snow"],
  // Found in the 0.5.11 architecture audit against the official block listing.
  // All three reached the world through a placement path, and all three failed
  // silently: setBlock swallows the throw, so the only symptom was missing
  // geometry (a savanna house with no foundation, a meadow house with no door,
  // a cobble watchtower with no roof).
  ["minecraft:terracotta", "minecraft:hardened_clay"],
  ["minecraft:oak_door", "minecraft:wooden_door"],
  ["minecraft:stone_slab", "minecraft:smooth_stone_slab"]
]);

/**
 * Every block identifier any code has TRIED to place, valid or not.
 *
 * util.js's setBlock deliberately swallows placement errors so one bad
 * coordinate can't abort a whole build - which also swallows the mock's
 * "unknown block identifier" throw. So a functional test can't see a bad id
 * by catching anything. Recording the attempt makes it visible.
 *
 * This is what catches ids built at runtime (`minecraft:${p.wood}_door`),
 * which the source-scanning lint checks structurally cannot see: they exist
 * only once a palette has been resolved.
 */
const attemptedBlockIds = new Set();

function isKnownBadBlockId(typeId) {
  return KNOWN_INVALID_BLOCK_IDS.has(typeId);
}

function suggestionForBlockId(typeId) {
  return KNOWN_INVALID_BLOCK_IDS.get(typeId);
}

function assertRealBlockId(typeId) {
  attemptedBlockIds.add(typeId);
  const better = KNOWN_INVALID_BLOCK_IDS.get(typeId);
  if (better) {
    throw new Error(
      `InvalidArgumentError: unknown block identifier '${typeId}' - use '${better}'`
    );
  }
}

class BlockPermutation {
  static resolve(typeId, states) {
    if (typeId === "minecraft:__throw__") throw new Error("simulated bad state");
    assertRealBlockId(typeId);
    if (states) {
      const cat = categoryOf(typeId);
      const allowed = VALID_STATES[cat];
      if (allowed) {
        for (const k of Object.keys(states)) {
          if (!allowed.has(k)) {
            throw new Error(`invalid block state ${k} for ${typeId}`);
          }
        }
      }
    }
    return { typeId, states: states || {} };
  }
}

function makeBlock(loc) {
  const k = key(loc);
  return {
    location: loc,
    get typeId() {
      const rec = blockStore.get(k);
      return rec ? rec.typeId : "minecraft:air";
    },
    get permutation() {
      const rec = blockStore.get(k) || { typeId: "minecraft:air", states: {} };
      return {
        typeId: rec.typeId,
        getState(name) {
          if (!(name in (rec.states || {}))) throw new Error("no such state " + name);
          return rec.states[name];
        },
        withState(name, value) {
          return { typeId: rec.typeId, states: { ...(rec.states || {}), [name]: value } };
        }
      };
    },
    setType(typeId) {
      // Real setType is simpler than setPermutation+states: it never
      // needs to validate a states object, so it should basically never
      // throw for a real block id. Mirror that leniency here - reject
      // only our one deliberately-fake "always throws" sentinel id.
      if (typeId === "minecraft:__throw__") throw new Error("simulated bad block");
      // ...but a NON-EXISTENT id is a different case: the real engine rejects
      // those, and the mock accepting them is what let bad ids ship silently.
      assertRealBlockId(typeId);
      blockStore.set(k, { typeId, states: {} });
      if ((typeId === "minecraft:chest" || typeId === "minecraft:barrel") && !containerStore.has(k)) {
        containerStore.set(k, makeContainer());
      }
    },
    setPermutation(perm) {
      if (perm?.typeId) attemptedBlockIds.add(perm.typeId);
      blockStore.set(k, perm);
      if ((perm.typeId === "minecraft:chest" || perm.typeId === "minecraft:barrel") && !containerStore.has(k)) {
        containerStore.set(k, makeContainer());
      }
    },
    getComponent(name) {
      if (name === "minecraft:sign") {
        if (!(blockStore.get(k) || {}).typeId?.includes("sign")) return undefined;
        return {
          setText(text) { signStore.set(k, text); },
          getText() { return signStore.get(k); }
        };
      }
      if (name === "minecraft:inventory") {
        if (!containerStore.has(k)) return undefined;
        return { container: containerStore.get(k) };
      }
      return undefined;
    }
  };
}

/**
 * Item identifiers that look plausible but do not exist in Bedrock. Same
 * reasoning as KNOWN_INVALID_BLOCK_IDS above: the mock accepting anything is
 * what let `minecraft:map` sit in the cartographer's final quest step, where
 * it made that step impossible to hand in on a real device (Bedrock has
 * `empty_map` and `filled_map`, and no plain `map`).
 *
 * Confirmed against the official item listing at
 * learn.microsoft.com/minecraft/creator/reference/content/vanillalistingsreference/items.
 */
const KNOWN_INVALID_ITEM_IDS = new Map([
  ["minecraft:map", "minecraft:empty_map"]
]);

function assertRealItemId(typeId) {
  const better = KNOWN_INVALID_ITEM_IDS.get(typeId);
  if (better) {
    throw new Error(
      `InvalidArgumentError: unknown item identifier '${typeId}' - use '${better}'`
    );
  }
}

/**
 * Bow/tool enchantments this engine build knows about. EnchantmentTypes.get
 * returns undefined for anything else, exactly like the real catalogue does
 * for an id that has been renamed - which is the case addon code has to
 * survive without losing the whole transaction.
 */
const KNOWN_ENCHANTMENTS = new Map([
  ["minecraft:power", 5], ["minecraft:flame", 1], ["minecraft:punch", 2],
  ["minecraft:infinity", 1], ["minecraft:unbreaking", 3], ["minecraft:mending", 1],
  ["minecraft:sharpness", 5], ["minecraft:efficiency", 5], ["minecraft:fortune", 3],
  ["minecraft:protection", 4]
]);

class EnchantmentType {
  constructor(enchantmentType) {
    if (!KNOWN_ENCHANTMENTS.has(enchantmentType)) {
      throw new Error(`EnchantmentTypeUnknownIdError: '${enchantmentType}'`);
    }
    this.id = enchantmentType;
    this.maxLevel = KNOWN_ENCHANTMENTS.get(enchantmentType);
  }
}

const EnchantmentTypes = {
  get(enchantmentId) {
    return KNOWN_ENCHANTMENTS.has(enchantmentId) ? new EnchantmentType(enchantmentId) : undefined;
  },
  getAll() {
    return Array.from(KNOWN_ENCHANTMENTS.keys(), (id) => new EnchantmentType(id));
  }
};

class ItemStack {
  constructor(typeId, amount) {
    assertRealItemId(typeId);
    this.typeId = typeId;
    this.amount = amount === undefined ? 1 : amount;
    this.nameTag = undefined;
    this._lore = [];
    this._enchantments = [];
  }

  // Real ItemStack.clone() carries the name tag, lore and enchantments across;
  // a rollback that rebuilt stacks from typeId+amount alone would silently
  // strip a named reward, so the mock has to copy them too.
  clone() {
    const copy = new ItemStack(this.typeId, this.amount);
    copy.nameTag = this.nameTag;
    copy._lore = [...this._lore];
    copy._enchantments = this._enchantments.map((entry) => ({ ...entry }));
    // A potion's effect is item data, so it has to survive a clone the same
    // way an enchantment does - otherwise a rollback would silently turn a
    // healing potion back into a plain bottle.
    copy._potionEffect = this._potionEffect;
    copy._potionDelivery = this._potionDelivery;
    return copy;
  }

  setLore(loreList) {
    const lines = loreList || [];
    if (lines.length > 20) throw new Error("ArgumentOutOfBoundsError: at most 20 lore lines");
    for (const line of lines) {
      if (typeof line === "string" && line.length > 50) {
        throw new Error(`ArgumentOutOfBoundsError: lore line longer than 50 characters: '${line}'`);
      }
    }
    this._lore = [...lines];
  }

  getLore() { return [...this._lore]; }

  getComponent(componentId) {
    if (componentId !== "minecraft:enchantable" && componentId !== "enchantable") return undefined;
    const stack = this;
    return {
      addEnchantment(enchantment) {
        const type = enchantment?.type;
        if (!(type instanceof EnchantmentType)) {
          // The native layer takes an EnchantmentType, not a bare id string;
          // passing a string type-checks fine in plain JS and only fails
          // on-device, so reject it here instead.
          throw new Error("Native variant type conversion failed: Enchantment.type must be an EnchantmentType");
        }
        if (!Number.isInteger(enchantment.level) || enchantment.level < 1 || enchantment.level > type.maxLevel) {
          throw new Error(`EnchantmentLevelOutOfBoundsError: ${type.id} level ${enchantment.level}`);
        }
        stack._enchantments.push({ type, level: enchantment.level });
      },
      getEnchantments() { return stack._enchantments.map((entry) => ({ ...entry })); },
      hasEnchantment(enchantmentType) {
        const id = typeof enchantmentType === "string" ? enchantmentType : enchantmentType?.id;
        return stack._enchantments.some((entry) => entry.type.id === id);
      }
    };
  }
}

/**
 * Potion creation, modelled closely enough to catch the bug it exists for.
 *
 * A potion's effect lives in the item's potion data, NOT in its identifier:
 * `new ItemStack("minecraft:potion")` is the default, effectless bottle, so
 * an alchemist selling a "healing potion" that way is selling nothing. The
 * real API is Potions.resolve(effectType, deliveryType)
 * (learn.microsoft.com/minecraft/creator/scriptapi/minecraft/server/potions),
 * which throws InvalidPotionEffectTypeError / InvalidPotionDeliveryTypeError
 * for an id it does not know - so the mock throws too, rather than accepting
 * any string and handing back a stack that looks right.
 *
 * The resolved stack carries `_potionEffect` so a test can assert the player
 * actually received a *healing* potion and not just "a potion".
 */
const KNOWN_POTION_EFFECTS = new Set([
  "healing", "harming", "night_vision", "swiftness", "slowness", "strength",
  "weakness", "poison", "regeneration", "fire_resistance", "water_breathing",
  "invisibility", "leaping", "turtle_master", "slow_falling", "wither"
]);
const KNOWN_POTION_DELIVERIES = new Set(["regular", "splash", "lingering"]);

const Potions = {
  getEffectType(potionEffectId) {
    return KNOWN_POTION_EFFECTS.has(potionEffectId) ? { id: potionEffectId } : undefined;
  },
  getDeliveryType(potionDeliveryId) {
    return KNOWN_POTION_DELIVERIES.has(potionDeliveryId) ? { id: potionDeliveryId } : undefined;
  },
  getAllEffectTypes() { return Array.from(KNOWN_POTION_EFFECTS, (id) => ({ id })); },
  getAllDeliveryTypes() { return Array.from(KNOWN_POTION_DELIVERIES, (id) => ({ id })); },
  resolve(potionEffectType, potionDeliveryType) {
    const effect = typeof potionEffectType === "string" ? potionEffectType : potionEffectType?.id;
    const delivery = typeof potionDeliveryType === "string" ? potionDeliveryType : potionDeliveryType?.id;
    if (!KNOWN_POTION_EFFECTS.has(effect)) {
      throw new Error(`InvalidPotionEffectTypeError: '${effect}'`);
    }
    if (!KNOWN_POTION_DELIVERIES.has(delivery)) {
      throw new Error(`InvalidPotionDeliveryTypeError: '${delivery}'`);
    }
    const stack = new ItemStack("minecraft:potion", 1);
    stack._potionEffect = effect;
    stack._potionDelivery = delivery;
    return stack;
  }
};

/**
 * Structure placement, modelled closely enough to be worth testing against.
 *
 * The mock had none of this, so the whole structure pipeline would have been
 * untestable - and its point is precisely that a missing structure must be a
 * loud, catchable condition rather than a building that quietly fails to
 * appear. So the parts that decide that are the parts modelled:
 *
 *  - getPackStructureIds() lists what a behavior pack contains, and starts
 *    empty, which is the real state of this pack today;
 *  - place() throws InvalidStructureError for an unknown id, exactly as the
 *    engine does, instead of silently doing nothing;
 *  - a placed structure writes its blocks into the same blockStore the rest of
 *    the mock uses, so a palette swap pass can actually find them;
 *  - placement records the location and rotation it was asked for, so the
 *    facing-to-rotation mapping can be pinned by a test.
 *
 * Unlike setBlock, place() does NOT skip unloaded chunks: the documentation
 * says placement in an unloaded chunk is queued for loading. That difference
 * is the second reason the pipeline exists, so the mock reproduces it.
 */
const packStructures = new Map();   // id -> { size, blocks: [{x,y,z,typeId}] }
const worldStructures = new Map();
const structurePlacements = [];

const structureManager = {
  getPackStructureIds() { return Array.from(packStructures.keys()); },
  getWorldStructureIds() { return Array.from(worldStructures.keys()); },
  get(identifier) {
    return packStructures.get(identifier) || worldStructures.get(identifier) || undefined;
  },
  place(structure, dimension, location, options) {
    const id = typeof structure === "string" ? structure : structure?.id;
    const found = packStructures.get(id) || worldStructures.get(id);
    if (!found) throw new Error(`InvalidStructureError: no structure named '${id}'`);
    const rotation = options?.rotation ?? "None";
    structurePlacements.push({ id, location: { ...location }, rotation, options: { ...(options || {}) } });
    // Blocks are written at their authored offsets. Rotation is recorded but
    // not applied: what the tests need to pin is which rotation was ASKED for,
    // and reimplementing the engine's rotation here would only be testing this
    // mock's arithmetic against itself.
    for (const block of found.blocks || []) {
      const at = { x: location.x + block.x, y: location.y + block.y, z: location.z + block.z };
      blockStore.set(key(at), { typeId: block.typeId, states: {} });
    }
  },
  createFromWorld(identifier, dimension, from, to, options) {
    const blocks = [];
    const x1 = Math.min(from.x, to.x), x2 = Math.max(from.x, to.x);
    const y1 = Math.min(from.y, to.y), y2 = Math.max(from.y, to.y);
    const z1 = Math.min(from.z, to.z), z2 = Math.max(from.z, to.z);
    for (let x = x1; x <= x2; x++) {
      for (let y = y1; y <= y2; y++) {
        for (let z = z1; z <= z2; z++) {
          const rec = blockStore.get(key({ x, y, z }));
          if (rec) blocks.push({ x: x - x1, y: y - y1, z: z - z1, typeId: rec.typeId });
        }
      }
    }
    const made = { id: identifier, size: { x: x2 - x1 + 1, y: y2 - y1 + 1, z: z2 - z1 + 1 }, blocks };
    worldStructures.set(identifier, made);
    return made;
  },
  delete(structure) {
    const id = typeof structure === "string" ? structure : structure?.id;
    return worldStructures.delete(id) || packStructures.delete(id);
  }
};

function dist(a, b) {
  const dx = a.x - b.x, dy = a.y - b.y, dz = a.z - b.z;
  return Math.sqrt(dx * dx + dy * dy + dz * dz);
}

function makeDimension() {
  // Simulated "cold" regions: getBlock/spawnEntity throw the same error the
  // real engine throws for a chunk that isn't loaded yet, until a test
  // explicitly clears the region (standing in for chunk load completing a
  // few ticks after /tickingarea add runs).
  const unloadedRects = [];
  function isUnloaded(loc) {
    return unloadedRects.some(r => loc.x >= r.x1 && loc.x <= r.x2 && loc.z >= r.z1 && loc.z <= r.z2);
  }
  function assertLoaded(loc) {
    if (isUnloaded(loc)) {
      throw new Error(`LocationInUnloadedChunkError: Trying to access location (${loc.x}, ${loc.y}, ${loc.z}) which is not in a chunk currently loaded and ticking.`);
    }
  }
  const commands = [];
  // Biome patches a test has painted, newest first (unshift), so a later call
  // overrides an overlapping earlier one. Anything unpainted is plains.
  const biomes = [];
  return {
    playSound(id, loc) { /* no-op in tests */ },
    runCommand(cmd) { commands.push(cmd); return { successCount: 1 }; },
    _commands: commands,
    _markUnloaded(rect) { unloadedRects.push(rect); },
    _clearUnloaded() { unloadedRects.length = 0; },
    getBlock(loc) { assertLoaded(loc); return makeBlock(loc); },
    // The engine's own "will a write here land?" check (stable API). Mirrors
    // the simulated cold regions so tests can exercise the same branch.
    isChunkLoaded(loc) { return !isUnloaded(loc); },
    spawnEntity(typeId, loc, options) {
      assertLoaded(loc);
      // Real engine (1.21.80+) rejects a spawn event folded into the
      // identifier string outright - this is exactly the regression from
      // Bugfix Round 3 (ADULT_VILLAGER = "type<event>"), which slipped
      // past the old mock because it silently accepted and normalized the
      // string instead of rejecting it like the real engine does. Any
      // future code that reintroduces this pattern should fail here too.
      if (typeId.includes("<")) {
        throw new Error("InvalidArgumentError: Invalid value passed to argument [2]. Invalid identifier: Spawn event set via the entity identifier is deprecated, use spawnEvent in SpawnEntityOptions instead.");
      }
      const tags = new Set();
      const props = new Map();
      const entity = {
        typeId,
        _spawnEvent: options?.spawnEvent,
        location: { ...loc },
        dimension: dim,
        nameTag: "",
        addTag(t) { tags.add(t); return true; },
        // Real Entity has removeTag (returns whether the tag was there). The
        // mock never did, so code that dropped a tag - a guard letting go of
        // its tether to walk a patrol - blew up here rather than in the game.
        removeTag(t) { return tags.delete(t); },
        hasTag(t) { return tags.has(t); },
        getTags() { return Array.from(tags); },
        setDynamicProperty(k2, v) { props.set(k2, v); },
        getDynamicProperty(k2) { return props.get(k2); },
        triggerEvent(name) { entity._events = entity._events || []; entity._events.push(name); },
        _health: { current: 100, max: 100 },
        getComponent(name) {
          if (name === "minecraft:health") {
            return {
              get currentValue() { return entity._health.current; },
              get effectiveMax() { return entity._health.max; },
              setCurrentValue(v) { entity._health.current = v; }
            };
          }
          return undefined;
        },
        teleport(loc) { entity.location = { ...loc }; entity._teleports = (entity._teleports||0)+1; },
        tryTeleport(loc) { entity.location = { ...loc }; entity._teleports = (entity._teleports||0)+1; return true; },
        lookAt() { /* rotation is not modelled */ },
        get isValid() { return true; }
      };
      entities.push(entity);
      return entity;
    },
    /**
     * Dimension.getBiome(location) -> BiomeType, stable since 2.3.0.
     *
     * This was missing entirely, and its absence hid a whole subsystem: the
     * only caller, paletteAt() in palettes.js, wraps it in try/catch and falls
     * back to plains, so every one of the sixty suites was silently exercising
     * the fallback and nothing else. BIOME_TO_PALETTE, the ten .biome.json
     * files and four of the five palettes were untested by construction.
     *
     * Shape per the docs: a read-only `id` string, plus getTags/hasTags.
     * Defaults to minecraft:plains, which is what an unset test world is.
     */
    _biomes: biomes,
    _setBiome(rect, biomeId) { biomes.unshift({ ...rect, biomeId }); },
    _clearBiomes() { biomes.length = 0; },
    getBiome(loc) {
      assertLoaded(loc);
      const patch = biomes.find((b) => loc.x >= b.x1 && loc.x <= b.x2 && loc.z >= b.z1 && loc.z <= b.z2);
      const id = patch ? patch.biomeId : "minecraft:plains";
      return { id, getTags: () => [], hasTags: () => false };
    },
    getEntities(query) {
      return entities.filter((e) => {
        if (query.type && e.typeId !== query.type) return false;
        if (query.tags && !query.tags.every((t) => e.hasTag && e.hasTag(t))) return false;
        if (query.location && query.maxDistance !== undefined) {
          if (dist(e.location, query.location) > query.maxDistance) return false;
        }
        return true;
      });
    }
  };
}

const dim = makeDimension();

function makePlayer(name, loc) {
  // A player's inventory is 36 slots (9 hotbar + 27), and it obeys exactly the
  // same addItem contract as any other Container - including returning the
  // overflow it could not place. This used to be a second, more naive copy of
  // makeContainer that never stacked and never reported overflow, which is
  // precisely where the reward-destroying turn-ins were invisible, since every
  // quest reward is written into a player container.
  const container = makeContainer(36);
  container.items = container._raw;
  const tags = new Set();
  const player = {
    typeId: "minecraft:player",
    name,
    location: { ...loc },
    dimension: dim,
    isSneaking: false,
    nameTag: name,
    addTag(t) { tags.add(t); return true; },
    removeTag(t) { return tags.delete(t); },
    hasTag(t) { return tags.has(t); },
    getTags() { return Array.from(tags); },
    getViewDirection() { return { x: 1, y: 0, z: 0 }; },
    _mainhand: undefined,
    getComponent(name2) {
      if (name2 === "minecraft:inventory") return { container };
      if (name2 === "minecraft:equippable") {
        return { getEquipment(slot) { return player._mainhand; } };
      }
      return undefined;
    },
    // Player extends Entity, so it has dynamic properties like any other
    // entity. The mock only gave them to spawnEntity's result, so per-player
    // state - a flag saying this player has already been greeted, say - could
    // not be modelled at all: the write threw and the caller's error path ran
    // instead of its real one.
    _props: new Map(),
    setDynamicProperty(key, value) {
      if (value === undefined) player._props.delete(key);
      else player._props.set(key, value);
    },
    getDynamicProperty(key) { return player._props.get(key); },
    getDynamicPropertyIds() { return Array.from(player._props.keys()); },

    // The raw value is kept as well as the log line: a RawMessage is an object,
    // and interpolating it into a string turns the whole thing into
    // "[object Object]" - which is exactly the shape a test needs to inspect.
    locatorBar: makeLocatorBar(),

    _messages: [],
    sendMessage(msg) {
      player._messages.push(msg);
      messageLog.push(`[to ${name}] ${typeof msg === "string" ? msg : JSON.stringify(msg)}`);
      console.log(`[MSG->${name}]`, typeof msg === "string" ? msg : JSON.stringify(msg));
    }
  };
  entities.push(player);
  // world.getPlayers() reads world._players, which makePlayer never filled -
  // so five background loops that iterate players (dialogue, fortification
  // repair, livestock, patrol, worldgen) simply never ran a single iteration
  // in any suite unless that suite pushed the player in by hand.
  if (!world._players.includes(player)) world._players.push(player);
  return player;
}

/**
 * The locator bar (the compass strip at the top of the screen).
 *
 * `Player.locatorBar`, `LocationWaypoint` and `WaypointTexture` all arrived in
 * @minecraft/server 2.8.0. Modelled here to the contract the docs state:
 *
 *  - addWaypoint throws if the waypoint is already there, if maxCount is
 *    reached, or if it is not a waypoint at all;
 *  - removeWaypoint throws if the waypoint is not in the bar;
 *  - a pack may only see and modify waypoints it added itself, so everything
 *    in this bar belongs to us;
 *  - invalid waypoints are dropped by the engine on the next tick.
 *
 * One number is deliberately NOT asserted anywhere: the real `maxCount`. The
 * docs describe it as "the maximum number of waypoints that can be added" but
 * never say what it is, so guessing a value here and testing against it would
 * be inventing a fact. The mock's cap is small on purpose - overflow is the
 * interesting path - and any code under test has to read `maxCount` rather
 * than assume a number.
 */
export const WaypointTexture = Object.freeze({
  Circle: "minecraft:circle",
  SmallSquare: "minecraft:small_square",
  SmallStar: "minecraft:small_star",
  Square: "minecraft:square"
});

const WAYPOINT_TEXTURES = new Set(Object.values(WaypointTexture));

export class LocatorBarError extends Error {
  constructor(message, reason) { super(message); this.name = "LocatorBarError"; this.reason = reason; }
}
export class InvalidWaypointError extends Error {
  constructor(message) { super(message); this.name = "InvalidWaypointError"; }
}

export class LocationWaypoint {
  constructor(dimensionLocation, textureSelector, color) {
    this.dimensionLocation = dimensionLocation;
    this.textureSelector = textureSelector;
    this.color = color;
  }
  /** What the engine rejects: a bad location, or a texture it does not know. */
  get _valid() {
    const at = this.dimensionLocation;
    if (!at || !Number.isFinite(at.x) || !Number.isFinite(at.y) || !Number.isFinite(at.z)) return false;
    const bounds = this.textureSelector?.textureBoundsList;
    if (!Array.isArray(bounds) || bounds.length === 0) return false;
    return bounds.every((entry) => WAYPOINT_TEXTURES.has(entry?.texture));
  }
}

/** Test-tunable so the overflow path is reachable without a magic number. */
let waypointCap = 6;

function makeLocatorBar() {
  const waypoints = [];
  return {
    get count() { return waypoints.length; },
    get maxCount() { return waypointCap; },
    addWaypoint(waypoint) {
      if (!(waypoint instanceof LocationWaypoint) || !waypoint._valid) {
        throw new InvalidWaypointError("InvalidWaypointError: the waypoint is not valid.");
      }
      if (waypoints.includes(waypoint)) {
        throw new LocatorBarError("LocatorBarError: waypoint already exists.", "WaypointAlreadyExists");
      }
      if (waypoints.length >= waypointCap) {
        throw new LocatorBarError(`LocatorBarError: the locator bar is full (${waypointCap}).`, "MaxWaypointsReached");
      }
      waypoints.push(waypoint);
    },
    removeWaypoint(waypoint) {
      const at = waypoints.indexOf(waypoint);
      if (at < 0) throw new LocatorBarError("LocatorBarError: waypoint not found.", "WaypointNotFound");
      waypoints.splice(at, 1);
    },
    hasWaypoint(waypoint) { return waypoints.includes(waypoint); },
    getAllWaypoints() { return waypoints.slice(); },
    removeAllWaypoints() { waypoints.length = 0; }
  };
}

// The real engine forbids calling world natives while the script file is
// still being evaluated ("early execution"). Reproducing that here is what
// lets the lint suite catch load-time crashes before they reach the game.
function assertNotEarly(fnName) {
  if (world._earlyExecution) {
    throw new ReferenceError(`Native function [World::${fnName}] cannot be used in early execution.`);
  }
}

export const world = {
  _players: [],
  _absoluteTime: 0,
  _timeOfDay: 6000,
  _earlyExecution: false,
  getTimeOfDay() { assertNotEarly("getTimeOfDay"); return world._timeOfDay; },
  setTimeOfDay(t) { world._timeOfDay = t; },
  // Real World has getDay (world time divided by ticks per day, new worlds
  // start at 0). The mock had absolute time but never exposed the day, so
  // anything that rotates on it - a daily contract - could not be tested.
  _day: 0,
  getDay() { return world._day; },
  setDay(d) { world._day = d; },
  getAbsoluteTime() { return world._absoluteTime; },

  /**
   * World-scoped dynamic properties, with the engine's real string ceiling.
   *
   * The mock had none at all, so world-scoped storage could not be tested -
   * only per-entity properties existed here. That matters now the village
   * registry lives in world properties: the whole reason it is paged is the
   * 32,767-byte cap on a string value, and a mock that accepted a string of
   * any length would let a broken pager pass while the real engine threw.
   *
   * The cap is per value and documented; the engine throws rather than
   * truncating, so this does too.
   */
  _dynamicProperties: new Map(),
  setDynamicProperty(key, value) {
    assertNotEarly("setDynamicProperty");
    if (typeof key !== "string" || key.length === 0) {
      throw new Error("InvalidArgumentError: dynamic property identifier must be a non-empty string");
    }
    if (typeof value === "string" && value.length > 32767) {
      throw new Error(
        `Error: dynamic property '${key}' string value is ${value.length} bytes, over the 32767 byte limit`);
    }
    if (value === undefined) world._dynamicProperties.delete(key);
    else world._dynamicProperties.set(key, value);
  },
  getDynamicProperty(key) {
    assertNotEarly("getDynamicProperty");
    return world._dynamicProperties.get(key);
  },
  getDynamicPropertyIds() {
    assertNotEarly("getDynamicPropertyIds");
    return Array.from(world._dynamicProperties.keys());
  },
  getDynamicPropertyTotalByteCount() {
    let total = 0;
    for (const [key, value] of world._dynamicProperties) {
      total += key.length + (typeof value === "string" ? value.length : 8);
    }
    return total;
  },
  clearDynamicProperties() {
    assertNotEarly("clearDynamicProperties");
    world._dynamicProperties.clear();
  },

  get structureManager() { assertNotEarly("structureManager"); return structureManager; },
  getDimension(name) { assertNotEarly("getDimension"); return dim; },
  getPlayers() { assertNotEarly("getPlayers"); return world._players; },
  sendMessage(msg) {
    assertNotEarly("sendMessage");
    messageLog.push(`[broadcast] ${msg}`);
    console.log("[BROADCAST]", msg);
  },
  afterEvents: {
    itemUse: { subscribe() {} },
    // playerSpawn fires on respawn as well as first join, and initialSpawn is
    // what separates them - so the mock lets a test drive either, rather than
    // only the case the code happens to handle.
    playerSpawn: {
      _handlers: [],
      subscribe(handler) { world.afterEvents.playerSpawn._handlers.push(handler); return handler; },
      unsubscribe(handler) {
        const at = world.afterEvents.playerSpawn._handlers.indexOf(handler);
        if (at >= 0) world.afterEvents.playerSpawn._handlers.splice(at, 1);
      }
    }
  },
  /** Fires playerSpawn for one player, as the engine would. */
  _spawnPlayer(player, initialSpawn = true) {
    for (const handler of world.afterEvents.playerSpawn._handlers) handler({ player, initialSpawn });
  },
  beforeEvents: {
    playerInteractWithEntity: { subscribe() {} }
  }
};

export const system = {
  _deferred: [],
  // The real system.run defers to the next tick, so work scheduled during
  // early execution runs later, once world APIs are legal. Mirror that here
  // instead of firing synchronously, or the mock would report failures the
  // real engine never sees (and hide ones it does).
  run(fn) {
    if (world._earlyExecution) { system._deferred.push(fn); return system._deferred.length; }
    fn();
    return 0;
  },
  flushDeferred() {
    const queued = system._deferred.splice(0);
    for (const fn of queued) fn();
    return queued.length;
  },
  _intervals: [],
  runInterval(fn, ticks) { system._intervals.push(fn); return system._intervals.length; },
  _timeouts: [],
  // Fires immediately by default (matching system.run's non-early-execution
  // behaviour) so existing tests observe results synchronously without
  // needing to know this exists. A test that specifically wants to control
  // the delay (to reproduce a chunk-not-loaded-yet race) sets
  // system._deferTimeouts = true, then calls system.flushTimeouts() once it
  // wants to simulate the delay having elapsed.
  _deferTimeouts: false,
  runTimeout(fn, ticks) {
    if (system._deferTimeouts) { system._timeouts.push(fn); return system._timeouts.length; }
    fn();
    return 0;
  },
  flushTimeouts() {
    const queued = system._timeouts.splice(0);
    for (const fn of queued) fn();
    return queued.length;
  },
  // The real engine spreads a job generator's work across many ticks so a
  // heavy world edit never blocks long enough to trip the watchdog. This
  // mock has no tick loop to spread work across, so it drains the generator
  // to completion immediately - tests still observe the same final world
  // state as a synchronous call would have produced, while the production
  // code path (via the real system.runJob) gets genuine tick-spreading.
  runJob(generator) {
    let step = generator.next();
    while (!step.done) step = generator.next();
    return 0;
  }
};

export { BlockPermutation, ItemStack, EnchantmentType, EnchantmentTypes, Potions };
export const __test__ = {
  makeDimension: () => dim, makePlayer, blockStore, containerStore, signStore, entities, messageLog,
  attemptedBlockIds,
  isKnownBadBlockId,
  suggestionForBlockId,
  resetAttemptedBlockIds() { attemptedBlockIds.clear(); },

  // Stands in for a .mcstructure file shipped in the behavior pack. The real
  // pack has none yet, which is why the manifest is empty and the runtime
  // falls back - a test that wants the structure path has to say so.
  addPackStructure(id, size, blocks) {
    packStructures.set(id, { id, size, blocks: blocks || [] });
  },
  clearPackStructures() { packStructures.clear(); worldStructures.clear(); },
  structurePlacements,
  resetStructurePlacements() { structurePlacements.length = 0; }
};
